insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3eedda97-43cc-433a-95d4-4bf4878958cd', 'de', 'Sie ist voll dabei, und die Stimmung ist stark. Welcher selbstverständliche Abschluss hält den Schwung?', '["„Das machen wir noch mal. Gib mir deine Nummer.“", "„Hättest du Interesse, mich wiederzusehen?“", "„Wärst du offen dafür, mal was zu machen?“", "„Ich glaub, wir sollten uns vielleicht mal treffen?“"]'::jsonb, 'Geh davon aus, dass ihr Interesse da ist, und schlag den Plan direkt vor.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4051e636-695d-4534-936e-1f530668bf29', 'de', 'Warum wird ein Gespräch einseitig, wenn du zu viele Fragen hintereinander stellst?', '["Sie muss die meiste Arbeit machen", "Es fühlt sich wie Ausfragen an statt wie ein Austausch", "Sie zeigen, dass du aufmerksam bist"]'::jsonb, 'Fragen am laufenden Band schaffen ein Ungleichgewicht: Einer gibt, der andere nimmt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4533a8d2-717d-49b4-b4a9-c89b28985777', 'de', 'Sie sagt: „Ich bin gerade aus Japan zurück.“ Was könntest du darauf sagen?', '["Ihr von deinen eigenen Reisen erzählen", "Fragen: „Was hat dir in Japan am besten gefallen?“", "Das Thema wechseln und fragen, wo sie wohnt", "Sie dafür loben, dass sie reist"]'::jsonb, 'Wenn du an ihr Detail anknüpfst, vertieft sich das Gespräch ganz natürlich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48b2d089-1b51-4e26-9f2f-517c02891e1b', 'de', 'Welches Verhalten zeigt nonverbal, dass du dabei bist?', '["Dich ihr zuwenden, während sie spricht", "Durchgehend neutrale Miene", "Natürlicher Blickkontakt", "Dezentes Nicken an wichtigen Stellen"]'::jsonb, 'Zuwendung, Blickkontakt und Bewegungen, die auf sie reagieren, zeigen Präsenz.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('497c00d6-116b-4bf7-9ccf-9fdbef04ef82', 'de', 'Sie antwortet knapp zu ihrer Familie, und die Energie sinkt. Was könntest du als Nächstes tun?', '["Noch eine Frage zu ihrer Familie stellen", "Locker umlenken: „Und, wie schmeckt dein Essen?“", "Dich für den peinlichen Moment entschuldigen", "Sie fragen, warum sie so kurz geantwortet hat"]'::jsonb, 'Lenk ruhig auf neutrales Terrain um, damit der Schwung ohne Druck zurückkommt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4cd2af01-a10e-4c9e-b164-6c82a959ca1f', 'de', 'Warum schwächt es die Verbindung, wenn du unbedingt recht behalten willst?', '["Das Gespräch wird zum Wettkampf", "Es zeigt, dass dir Rechthaben wichtiger ist als die Verbindung", "Es zeigt, dass du sozial aufmerksam bist", "Sie fühlt sich im Unrecht statt einfach anders"]'::jsonb, 'Nicht die Meinungsverschiedenheit sorgt für Spannung, sondern der Drang, recht zu behalten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4d5ba9c1-712a-4d9d-b8a1-4ffec08ad96c', 'de', 'Welche Einstellung macht es möglich, zuzuhören, um zu verstehen?', '["Schlagfertige Antworten vorbereiten", "Ganz da sein, ohne vorauszuplanen", "Darauf achten, wie deine Geschichten zu ihren passen", "Schnell reagieren, um die Energie zu halten"]'::jsonb, 'Präsenz heißt, vorgeplante Antworten loszulassen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e01d376-3513-4958-b45f-3cbac7198e67', 'de', 'Ihr hattet ein tolles Gespräch über ihre anstehende Portugalreise. Zeit zu gehen. Was könntest du sagen?', '["„Schön, mit dir zu reden. Hab einen schönen Tag.“", "„Portugal klingt toll. Du musst mir erzählen, wie’s war.“", "„Gute Reise, wann immer du fährst.“"]'::jsonb, 'Hör mit einem konkreten Rückbezug auf. Das schafft einen roten Faden und einen natürlichen Grund, dich wieder zu melden.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e138ced-bcd3-4f4b-9394-d046b4bd81e7', 'de', 'Sie will ein Café ausprobieren, das du empfohlen hast. Gute Abschlüsse mit wenig Druck?', '["„Lass uns diese Woche zusammen hingehen. Hast du Samstag Zeit?“", "„Ich schick dir die Adresse. Was ist deine Nummer?“", "„Sag mir Bescheid, wie’s war, wenn du dort warst.“"]'::jsonb, 'Bitten mit wenig Druck senken die Abwehr. Halt sie klein, damit sich ein Ja natürlich anfühlt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('52c57688-6476-42cc-9677-4cb5e66512fd', 'de', 'Sie fragt: „Warum ist deine letzte Beziehung zu Ende gegangen?“ Welche Antwort ist am geerdetsten?', '["„Sie hat mich sehr verletzt, und ich hab immer noch daran zu knabbern.“", "„Es war toxisch und hat mich echt fertiggemacht.“", "„Wir wollten verschiedene Dinge, und ich hab dabei gelernt, was mir heute wichtiger ist.“"]'::jsonb, 'Diese Antwort ist ehrlich und zeigt trotzdem Abstand. Sie weckt Neugier, keine Sorge.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('535c49aa-9750-45dd-9796-69f61c22aedf', 'de', 'Welches Verhalten zeigt, dass jemand zuhört, um zu antworten, statt um zu verstehen?', '["Aufgreifen, was sie erzählt hat", "Schnell mit Ratschlägen kommen", "Sie unterbrechen, bevor sie fertig ist", "Antworten, die nichts mit ihrem letzten Punkt zu tun haben"]'::jsonb, 'Dieses Verhalten zeigt, dass es um Auftritt oder Kontrolle geht statt ums Verstehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('58d8c403-8e7d-4168-b8ba-758c4dff889c', 'de', 'Sie sagt: „Ich bin gerade aus Japan zurück.“ Was könntest du darauf sagen?', '["Ihr von deinen eigenen Reisen erzählen", "Fragen: „Was hat dir in Japan am besten gefallen?“", "Das Thema wechseln und fragen, wo sie wohnt", "Sie dafür loben, dass sie reist"]'::jsonb, 'Wenn du an ihr Detail anknüpfst, vertieft sich das Gespräch ganz natürlich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59ddb591-0f25-456d-abef-ddcf1bc55c9f', 'de', 'Sie erzählt von einer lustigen Reisepanne. Was könnte deine Geschichte als Antwort tun?', '["Mit einer ähnlich lustigen Anekdote mithalten", "Deine komplette Reisegeschichte erzählen", "Zu einem ganz anderen Thema springen", "Einen Rat geben, statt etwas zu erzählen"]'::jsonb, 'Halt es kurz und klar, um ihre Energie aufzugreifen und eine Verbindung aufzubauen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5def4588-2c49-4e7d-a78b-6de3a668455b', 'de', 'Warum bringen zu viele Fragen das Gespräch ins Ungleichgewicht?', '["Du holst Informationen raus, ohne selbst etwas beizutragen", "Fragen setzen sie unter Druck, etwas zu bieten und zu unterhalten", "Beides"]'::jsonb, 'Fragen am laufenden Band schaffen ein Ungleichgewicht: Einer gibt, der andere nimmt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6309d2eb-7004-43f3-99ec-c276acb5ec61', 'de', 'Sie hält intensiven Blickkontakt und fragt nach. Was zeigt das?', '["Sie ist abgelenkt und will das Gespräch beenden", "Das Gespräch braucht erst noch mehr Smalltalk", "Sie ist höflich, hat aber kein Interesse", "Sie bringt sich ein, und der Moment ist reif für den Abschluss"]'::jsonb, 'Aktive Neugier und positive Körpersprache zeigen, dass der Moment reif für den Abschluss ist.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('65941383-8920-456d-9564-8f938de86fed', 'de', 'Was hilft dir, anderer Meinung zu sein, ohne die Verbindung zu verlieren?', '["Deine Sicht als absolute Wahrheit darstellen", "Fragen stellen, wie sie zu ihrer Meinung kommt", "Im Ton ruhig bleiben", "Beide Sichtweisen nebeneinander stehen lassen"]'::jsonb, 'Die Verbindung bleibt, wenn ihr Unterschiede erkundet, statt sie abzuwerten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66cbe1b3-1585-4d3f-b00f-bb1fcf3143d3', 'de', 'Was passiert, wenn du weitermachst, ohne auf ihren Punkt einzugehen?', '["Du klingst gehetzt", "Es wirkt, als hättest du sie vielleicht nicht verstanden", "Es gibt weniger Gesprächsthemen", "Es bremst den Schwung"]'::jsonb, 'Würdigen zeigt Verständnis. Mach das, bevor du die nächste Frage stellst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('674acf71-26d4-428e-aa33-571e27f0d7d7', 'de', 'Warum fühlt sich das Anknüpfen an Fäden natürlicher an als Themensprünge?', '["Es ist so, wie Freunde wirklich miteinander reden", "Das Gespräch baut auf sich selbst auf, statt beliebig zu wirken", "Sie fühlt sich gehört, weil du auf das eingehst, was sie sagt", "Es baut auf sich selbst auf, und sie fühlt sich gehört"]'::jsonb, 'Anknüpfen schafft Fluss: Jede Antwort baut auf der vorigen auf.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('68abae72-376e-4c38-bd5f-a63ad5d4ed56', 'de', 'Sie erzählt kurz von einer stressigen Deadline, die sie gerade geschafft hat. Deine Reaktion?', '["Erst würdigen, dann von einer ähnlichen Herausforderung im Job erzählen, die du gemeistert hast", "Sofort Karrieretipps geben", "Zu deinen Wochenendplänen wechseln"]'::jsonb, 'Greif ihre Energie mit einer kurzen, passenden Geschichte auf, um eine Verbindung aufzubauen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6a3257d1-17bb-4df3-b9ca-c907755b7988', 'de', 'Was macht am Anfang eines Gesprächs eine gute Geschichte aus?', '["Einen bestimmten Moment mit emotionaler Wirkung auswählen", "So viele Details wie möglich einbauen", "Alles genau so erzählen, wie du es in Erinnerung hast", "Sie lang machen, um Tiefe zu zeigen"]'::jsonb, 'Ein knapper Ausschnitt dessen, was wichtig war, schafft schneller Verbindung als die ganze Geschichte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('72a6b099-3278-4a37-8a82-51225280d333', 'de', 'Was schafft positive emotionale Anker?', '["Echtes Lachen, kein höfliches, sondern echte Freude", "Würdigen, also anerkennen, was ihr wichtig ist", "Neugier, die sie anders über sich nachdenken lässt", "Alle oben genannten"]'::jsonb, 'Würdigen, Neugier und Lachen bringen Gefühle in Bewegung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('75148042-557e-4fcd-b9cf-a733e31a8702', 'de', 'Sie sagt: „Ich hab gerade meine Schwester in Portland besucht.“ Was könntest du darauf sagen?', '["„Reist du viel?“", "„Schön, dass du so ein enges Verhältnis zu deiner Schwester hast. Was habt ihr so gemacht?“", "„Portland ist toll. Warst du schon mal in Seattle?“", "„Wie lange warst du weg?“"]'::jsonb, 'Würdige erst, was sie erlebt hat, um Verständnis zu zeigen, bevor du darauf aufbaust.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('75dbf155-f762-4c46-a881-ee4691d19f29', 'de', 'Mit welcher Einstellung kommst du insgesamt besser zum Abschluss?', '["„Ich muss was festmachen.“", "„Daraus muss was werden.“", "„Jetzt oder nie.“", "„Lass uns einen kleinen Schritt weitergehen.“"]'::jsonb, 'Kleine Schritte senken die Abwehr. Halt deine Bitten klein, damit sich ein Ja natürlich anfühlt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('76af82d7-0b8b-4c02-ad43-4cff911e6e4f', 'de', 'Mit welcher Einstellung verabschiedest du dich insgesamt besser?', '["Auf Fäden achten, die du weiterspinnen kannst", "Auf gutes Timing hoffen", "Versuchen, in Erinnerung zu bleiben", "Schnell aufhören, um Peinlichkeit zu vermeiden"]'::jsonb, 'Wenn du an einen Faden anknüpfst, habt ihr einen natürlichen Grund, wieder Kontakt aufzunehmen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79854e99-6c36-4456-94b9-a4a09f901b6e', 'de', 'Warum schafft Würdigen psychologische Sicherheit?', '["Menschen fühlen sich mit dem, was sie erleben, anerkannt und verstanden", "Es zeigt emotionale Intelligenz und Empathie", "Würdigen gibt Menschen das Gefühl, wichtig und geschätzt zu sein"]'::jsonb, 'Wenn sie sich verstanden fühlt, öffnet sie sich ganz natürlich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7f4038e9-35fa-4928-b87c-513fe0b81ce9', 'de', 'Sie erwähnt einen stressigen Tag. Was solltest du vermeiden?', '["Sagen: „Hier kann ich nach einem langen Tag immer gut abschalten.“", "Fragen: „Was hat deinen Tag so stressig gemacht?“", "Sagen: „Du wirkst, als könntest du gut mit Stress umgehen.“"]'::jsonb, 'Verbinde dich mit positiven Gefühlen. Quetsch sie nicht über ihren Stress aus.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8105c1a4-951f-4041-9374-fb7c65a70dca', 'de', 'Welche Fäden bietet dir „Ich bin Anwältin“?', '["Ihre genaue Rolle und ihre Aufgaben", "In welchem Rechtsgebiet sie arbeitet", "Ihre Berufserfahrung und ihren Werdegang", "Alle oben genannten"]'::jsonb, 'An einem Faden anknüpfen heißt, ihr Thema zu vertiefen. Frag konkret nach dem, was sie erwähnt hat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8389bf63-7797-4fed-8bf2-0f7cb7b996c7', 'de', 'Das Gespräch läuft gut, und sie lacht. Was könntest du sagen, um ganz selbstverständlich zum Abschluss zu kommen?', '["„Hättest du vielleicht mal Lust auf einen Kaffee?“", "„Ich weiß nicht, aber vielleicht könnten wir mal was machen?“", "„Willst du Nummern tauschen?“", "„Lass uns einen Kaffee trinken gehen. Was ist deine Nummer?“"]'::jsonb, 'Sag den nächsten Schritt selbstbewusst als Tatsache, statt um Erlaubnis zu fragen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8424db00-09f4-4aa8-b16b-d90b7a683c0b', 'de', 'Warum verringern lange Monologe die Anziehung?', '["Sie klingen einstudiert", "Sie nehmen ihr die Chance, sich einzubringen", "Sie bremsen das Gespräch", "Sie verraten zu viel"]'::jsonb, 'Wenn sie nichts beitragen kann, bringt sie sich weniger ein. Lass ihr Raum, etwas zu erzählen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8578c723-b332-450d-8dd1-4eaad1b6150b', 'de', 'Warum solltest du deine Geschichte mit ihrer Welt verknüpfen?', '["Es entsteht ein gemeinsamer Austausch statt zweier Geschichten nebeneinander", "Es zeigt, dass du die Geschichte nutzt, um sie zu verstehen", "Es verhindert, dass das Gespräch auseinanderfällt", "Alle oben genannten"]'::jsonb, 'Durch den Bezug wird die Geschichte zu einem Weg zur Verbindung, nicht nur zu einem Auftritt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('87339858-15ab-4a2b-89af-d6a42cafac7a', 'de', 'Was bewirken Sätze, mit denen du sie würdigst?', '["Sie zeigen, dass ihre Worte wirklich bei dir angekommen sind", "Sie schaffen Raum für einen echteren Austausch", "Sie zeigen Selbstbewusstsein und emotionale Aufmerksamkeit", "Sie halten sie im Moment, mit dem Gefühl, verstanden zu werden"]'::jsonb, 'Wenn du auf ihre Worte eingehst, zeigst du, dass du sie gehört hast, und das lädt sie ein, mehr zu erzählen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97b34e22-5615-4aa3-bf23-73f5718f67c6', 'de', 'Was hilft, damit eine Geschichte Verbindung schafft, statt in einer Sackgasse zu enden?', '["Damit enden, wie beeindruckend das Ergebnis war", "Fragen, wie sie zu der Situation steht", "Die Geschichte mit etwas verbinden, das sie schon erwähnt hat"]'::jsonb, 'Geschichten verbinden, wenn sie ihre Welt ins Gespräch holen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97e7b932-511e-48e1-bf8b-9b0e49bd18f9', 'de', 'Sie redet, und du merkst, dass du schon deine Antwort planst. Was solltest du tun?', '["Schnell fertig planen und dann wieder zuhören", "Aufhören zu planen und sofort wieder ganz bei ihren Worten sein", "Sie bitten, das Letzte zu wiederholen, weil du abgeschweift bist"]'::jsonb, 'Bemerk, dass du abschweifst, und hol deine Aufmerksamkeit sofort zurück zu ihren Worten und ihrem Ton.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('998825a4-01bc-40bc-9219-b9e8a227feb8', 'de', 'Nachdem du eine andere Meinung gesagt hast, spürst du Spannung. Wie lenkst du am saubersten um?', '["Sanfter im Ton werden und nach ihrer Erfahrung fragen", "Mit noch mehr Beweisen nachlegen", "Dich dafür entschuldigen, dass du anderer Meinung bist"]'::jsonb, 'Wechsel vom Beweisen zum Verstehen. Frag lieber nach ihrer Erfahrung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a3ada69-efcb-4e14-96d0-7d4c087e2d2a', 'de', 'Was tragen Beobachtungen und Aussagen vor allem zum Gespräch bei?', '["Sie gleichen den Austausch aus", "Sie zeigen deine eigene Sicht", "Sie verlangen von ihr eine Antwort"]'::jsonb, 'Sie machen das Gespräch zu etwas Gemeinsamem und Warmem.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9b82f398-1878-449a-baf9-24e1e9ec6c0d', 'de', 'Warum schafft es Verbindung, Verarbeitetes zu teilen?', '["Es zeigt Selbstreflexion und persönliche Entwicklung", "Es zeigt Verletzlichkeit, ohne sie emotional zu belasten", "Es lädt zu Nähe ein, ohne dass sie sich verpflichtet fühlt zu helfen", "Alle oben genannten"]'::jsonb, 'Verarbeitete Erlebnisse laden zu Verbindung ein, nicht dazu, dass sie sich um dich kümmern muss.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9bb0ed54-392a-4aab-9aed-715508c1df96', 'de', 'Du siehst einen Film anders als sie. Sie wirkt leidenschaftlich. Was könntest du als Nächstes tun?', '["Erklären, warum ihre Meinung falsch ist", "Sagen: „Spannende Sicht. Warum liebst du ihn so?“", "So tun, als würdest du zustimmen, damit es glatt läuft", "Sofort das Thema wechseln"]'::jsonb, 'Zeig Neugier auf ihre Begeisterung, dann bleibt ihr trotz unterschiedlicher Meinungen verbunden.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9d4b7485-9598-45ab-9df1-95a6de8dbd91', 'de', 'Sie sagt: „Ich hab diese Woche jeden Abend lange gearbeitet.“ Was könntest du darauf sagen?', '["„Was machst du beruflich?“", "„Klingt, als hättest du dir einen Abend draußen echt verdient.“", "„Wie viele Stunden arbeitest du?“", "„Bist du müde?“"]'::jsonb, 'Eine Aussage bringt etwas ein und lädt sie ohne Druck ein, mehr zu erzählen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f096c93-c6af-4940-a92a-503d7c7f4a16', 'de', 'Sie erzählt, dass ihr der neue Job schwerfällt. Du erzählst von deiner eigenen Erfahrung. Und dann?', '["„So war das bei mir auch. Na ja …“", "„Wie kommst du bisher mit der Umstellung klar?“", "„Was machst du genau?“"]'::jsonb, 'Stell den Bezug zu ihrer jetzigen Situation her, um sie nach ihrer Sicht zu fragen und die Verbindung zu vertiefen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f811f6d-ea33-440c-a2f7-4e4f2eab4134', 'de', 'Sie sagt, dass sie wegen der Arbeit gestresst ist. Welche Antwort schafft eine positive Verbindung?', '["„Klingt hart. Arbeit ist brutal.“", "„Du solltest versuchen, deine Zeit besser einzuteilen.“", "„Jeder ist heutzutage gestresst.“", "„Worauf freust du dich am meisten, wenn das vorbei ist?“"]'::jsonb, 'Das lenkt ihre Stimmung sanft von Stress zu Erleichterung und Vorfreude.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a3852cf6-c43a-47f6-95c6-432c2afa408f', 'de', 'Ihr geht zusammen, und das Gespräch wird langsamer. Was zeigt einen sauberen Neustart?', '["Eine entspannte Pause, bevor du umlenkst", "Schnelle Themenwechsel", "Fragen, ob sie sich langweilt"]'::jsonb, 'Ruhe zeigt mehr Selbstbewusstsein als Tempo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a567d0df-afca-4f4d-bed2-fa676a9cd119', 'de', 'Du merkst, dass sie nickt, aber kaum etwas beiträgt, während du redest. Was passt du am besten an?', '["Deinen Punkt kraftvoll zu Ende bringen", "Schneller reden, um fertig zu werden", "Innehalten und nach ihrer Sicht fragen", "Abrupt das Thema wechseln"]'::jsonb, 'Nachfragen bringt das Gleichgewicht zurück und lädt sie ein, wieder mitzumachen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a6a5fa05-f1d7-453b-b228-4c8e34485599', 'de', 'Was passiert, wenn du nur Fragen stellst?', '["Sie muss den ganzen Inhalt liefern", "Das Gespräch fühlt sich wie ein Verhör an, nicht wie Verbindung", "Sie wird vom ständigen Antworten müde", "Alle oben genannten"]'::jsonb, 'Zu viele Fragen wirken wie ein Ausfragen, bei dem sie das Gespräch allein trägt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a734d277-baef-4344-8dd3-962cd62d6ac3', 'de', 'Warum ist es wichtig, dass sie dich mit positiven Gefühlen verbindet?', '["Gefühle sorgen dafür, dass sie dich stärker mit etwas verbindet", "Positive Gefühle bringen sie dazu, mehr Zeit mit dir verbringen zu wollen", "Negative Gefühle bauen immer Anziehung auf"]'::jsonb, 'Anziehung entsteht aus dem, wie sie sich in deiner Nähe fühlt, nicht nur aus dem Inhalt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a89cc880-19f7-430e-b699-51926d19b98b', 'de', 'Sie äußert eine Meinung, die du nicht teilst. Welche Reaktion erhält die Verbindung am besten?', '["Erklären, warum ihre Sicht falsch ist", "Zustimmen, um Spannung zu vermeiden", "Sofort das Thema wechseln", "Ihre Sicht anerkennen und fragen, wie sie dazu gekommen ist"]'::jsonb, 'Neugier hält das Gespräch zu einem Miteinander statt zu einem Wettkampf.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a9785ffd-0cfe-4181-b029-10a0c6cc6131', 'de', '„Ich arbeite in der Tech-Branche, aber am Wochenende male ich.“ Welche Antwort knüpft am besten an?', '["„Tech und Kunst, spannende Kombi. Wie kam das?“", "„Oh, cool. Was machst du genau in der Tech-Branche?“", "„Malen! Wie toll. Was malst du?“"]'::jsonb, 'Verbindet beide Fäden, zeigt, dass du alles gehört hast, und öffnet die Tür für ihre Geschichte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('aa6e8752-217b-4419-a60b-1e74d05c3e39', 'de', 'Sie erzählt eine lustige Geschichte und lacht. Was sollte deine Körpersprache tun?', '["Völlig reglos und neutral bleiben", "Bei der Pointe lächeln und nicken", "Wegschauen, um nicht zu eifrig zu wirken", "Die Arme verschränken und dich zurücklehnen"]'::jsonb, 'Wenn du ihre Energie mit deiner Mimik aufgreifst, zeigst du echtes Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ab4ba3e7-8e8e-4347-a113-cdb95d15d251', 'de', 'Welches Verhalten bringt den Gesprächsrhythmus oft durcheinander?', '["Lange Geschichten ohne Pause", "Kurze Antworten ohne Nachfrage", "Kurz etwas erzählen und dann Raum lassen", "Nach einem Punkt nachfragen"]'::jsonb, 'Dominieren und Zurückziehen bringen den Rhythmus beide aus dem Gleichgewicht.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('add28003-e846-44f9-b448-3449baa804b7', 'de', 'Sie widerspricht deiner Meinung. Woran erkennst du, dass du gesund reagierst?', '["Du bleibst entspannt und im Gespräch", "Du zählst Beispiele auf, um recht zu behalten", "Du wirst lauter, um mitzuhalten", "Du ziehst dich aus dem Thema zurück"]'::jsonb, 'Wenn du entspannt bleibst, zeigst du, dass dich Widerspruch nicht aus der Ruhe bringt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('af3e39be-381e-451e-aa88-6cebba413dad', 'de', 'Welche Sätze würdigen das, was sie gesagt hat?', '["„Das klingt hart.“", "„Ich versteh, warum dir das wichtig ist.“", "„Warum ist das passiert?“", "„Das muss schwer gewesen sein.“"]'::jsonb, 'Kurze Anerkennung zeigt, dass ihre Worte Gewicht haben.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b14823ef-b8ce-4062-8fcb-4cfcf41fc931', 'de', 'Wann wird eine Meinungsverschiedenheit zum Problem?', '["Wenn Rechthaben wichtiger ist als die Verbindung", "Wenn die Meinungen zu verschieden sind, um Gemeinsamkeiten zu finden", "Wenn sie zu früh kommt, bevor Vertrauen da ist"]'::jsonb, 'Die Verbindung bricht, wenn Rechthaben wichtiger wird als Verstehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b284a2c4-70e8-4c60-91c5-92cbc5e68edf', 'de', 'Sie blüht auf, als sie von einem Hobby erzählt. Du musst los. Woran kannst du deinen letzten Satz ausrichten?', '["Effizient abschließen", "Druck vermeiden", "Es kurz halten", "Das aufgreifen, was sie so begeistert hat"]'::jsonb, 'Wenn du mit dem aufhörst, was ihr wichtig war, bleibt die Stimmung der Begegnung erhalten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b5ac4b83-5b84-4914-8cdf-cbba23aa7ff4', 'de', 'Ihr redet locker und lustig über eure Lieblings-Ramenläden. Wie kannst du zum Abschluss kommen?', '["„Wir sollten mal auf ein Date gehen. Darf ich dich zum Essen einladen?“", "„Ich schick dir den Ramenladen, den ich erwähnt hab. Was ist deine Nummer?“", "„Lass uns bald was machen. Wann hast du Zeit?“"]'::jsonb, 'Ein kleiner nächster Schritt ohne Druck passt zur Stimmung und fühlt sich natürlich an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b7fd7470-ddb6-4107-9390-97cff5fc0696', 'de', 'Warum macht ein allgemeiner Abschied den Schwung nach einem guten Gespräch kaputt?', '["Spätere Nachrichten wirken dann zusammenhanglos", "Sie hat nichts Konkretes, woran sie sich erinnern oder anknüpfen kann", "Er zeigt, dass du genau zugehört hast"]'::jsonb, 'Ein allgemeiner Abschied schließt die Begegnung ganz ab, statt eine Brücke nach vorn zu bauen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bac16dba-494e-42a6-85ef-76041bd6b867', 'de', 'Warum verhindert Zuhören, um zu antworten, echte Verbindung?', '["Dein Kopf ist bei deinem nächsten Satz statt bei ihren Worten", "Du verpasst Subtext und emotionale Signale", "Deine Antworten wirken allgemein und ohne Bezug", "Es zeigt, dass du ganz im Moment bist"]'::jsonb, 'Wer Antworten plant, ist mit dem Fokus bei sich und zeigt, dass er ihr nicht wirklich zuhört.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bb4ac1da-dc29-41e3-a551-022813ad2ba6', 'de', 'Sie sagt, dass sie am Wochenende Zeit hat. Welcher selbstverständliche Abschluss passt am besten?', '["„Hättest du Lust, essen zu gehen?“", "„Meinst du, wir sollten uns treffen?“", "„Dann sehen wir uns. Was ist deine Nummer?“", "„Vielleicht Essen, falls du Interesse hast?“"]'::jsonb, 'Geh vom Plan aus und kläre selbstbewusst das Praktische.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bf592d93-816d-437d-bf97-761e412be0fa', 'de', 'Warum schafft es Verbindung, auf den Subtext einzugehen?', '["Es zeigt, dass du über die wörtliche Bedeutung hinaus zuhörst", "Es hält das Gespräch an der Oberfläche", "Sie fühlt sich wirklich verstanden", "Es erkennt das Gefühl hinter ihren Worten an"]'::jsonb, 'Der Subtext zeigt die eigentliche Botschaft. Wenn du darauf eingehst, seid ihr aufeinander eingestimmt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c46c2263-5933-4984-8b1a-1cb44756f991', 'de', 'Warum verlieren lange, haarkleine Geschichten oft die Zuhörerin?', '["Sie wirken unehrlich", "Sie sind zu verletzlich", "Sie zeigen Unsicherheit", "Man muss sich zu viel merken"]'::jsonb, 'Wenn man sich anstrengen muss, um zu folgen, lässt die emotionale Verbindung nach.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c6ab667b-89c1-40bf-81ce-fc391a31cf88', 'de', 'Warum sollten Gespräche am Anfang leicht bleiben?', '["Für schwerere Themen braucht Vertrauen Zeit", "Unverarbeitetes zu teilen bringt alles aus dem Gleichgewicht", "Verarbeitete Details laden ganz natürlich zu Nähe ein", "Tiefe ist von Anfang an immer besser"]'::jsonb, 'Auf einer leichten Grundlage kann Verbindung sicher wachsen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c7773b16-20a8-4e4f-b8d5-ce0164ce4e7a', 'de', 'Warum lösen große Bitten auch nach einem guten Gespräch oft Zögern aus?', '["Plötzlich steht viel mehr auf dem Spiel", "Sie wirken einstudiert", "Sie klingen bedürftig", "Sie verringern die Anziehung"]'::jsonb, 'Wenn zu schnell zu viel auf dem Spiel steht, ziehen sich Menschen instinktiv zurück.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c8c65a67-7bdf-4ffa-95d7-4d6f1b019a36', 'de', 'Drei Fragen hintereinander. Sie antwortet, aber die Energie ist flach. Was solltest du als Nächstes tun?', '["Eine spannendere Frage stellen, um ihr Interesse zurückzuholen", "Zu einem Thema wechseln, für das sie sich mehr begeistert", "Eine Aussage oder Beobachtung machen, um den Austausch auszugleichen"]'::jsonb, 'Beobachtungen geben ihr etwas, worauf sie eingehen kann, ohne dass sie antworten muss.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c9c21217-6720-474d-becb-eea9a3d28503', 'de', 'Sie sagt: „Ich hab Psychologie studiert, bin aber im Produktdesign gelandet.“ Welche Fäden bieten sich an?', '["„Psychologie ist faszinierend. Meine Schwester macht das auch.“", "„Wo hast du Psychologie studiert?“", "„Ganz schöner Wechsel. Was hat dich von der Psychologie zum Design gezogen?“"]'::jsonb, 'Die Frage, was sie von der Psychologie zum Design gezogen hat, greift den Wechsel auf, den spannendsten Teil ihrer Aussage.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cb95d0ef-b417-4041-9b25-7d3df8389f7c', 'de', 'Was macht Beobachtungen im Gespräch wirksam?', '["Sie zeigen, dass du auf Details achtest", "Sie geben ihr etwas, worauf sie eingehen kann, ohne etwas zu verlangen", "Sie schaffen einen gemeinsamen Moment statt Ausfragen", "Sie zeigen großes Selbstbewusstsein"]'::jsonb, 'Beobachtungen zeigen Aufmerksamkeit, laden ohne Druck zu einer Antwort ein und ermuntern sie, etwas zu erzählen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cbd5d720-2cda-427f-b70b-062656b318b6', 'de', 'Was gehört im Gespräch zum „Anpassen“?', '["Ähnlich laut sprechen wie sie", "Dich der emotionalen Tiefe anpassen, auf der sie gerade erzählt", "Ihren Ton und ihre Art zu kommunizieren aufgreifen", "Ihren Meinungen zustimmen"]'::jsonb, 'Anpassen schafft Leichtigkeit, indem ihr euch im Ausdruck angleicht, nicht in der Meinung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cca7a715-1724-4e42-a043-6c5cfa837473', 'de', 'Sie erzählt etwas Persönliches über ihren Jobwechsel. Was solltest du als Nächstes tun?', '["Sofort einen Rat geben oder sie beruhigen", "Innehalten, Blickkontakt halten und nicken", "Gleich eine Nachfrage stellen", "Das Thema wechseln, um den Schwung zu halten"]'::jsonb, 'Stille gibt dem Gespräch Raum und vertieft den Moment.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cfd11024-05eb-4caa-a51a-88939ceb81d5', 'de', 'Was passiert meistens, wenn sich jemand im Subtext verstanden fühlt?', '["Die Antworten werden kürzer", "Die Person entspannt sich und erzählt mehr", "Sie wechselt das Thema", "Sie wird verschlossener"]'::jsonb, 'Wer sich verstanden fühlt, öffnet sich und erzählt mehr.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d226b626-28f6-4109-8268-b01d9a460890', 'de', 'Wozu dienen vor allem Nachfragen, die das Gesagte würdigen?', '["Um ihr Ratschläge zu ihrer Situation zu geben", "Um zu zeigen, dass ihre Antwort zählt, bevor es weitergeht", "Um elegant das Thema zu wechseln", "Um sofort tiefere Fragen zu stellen"]'::jsonb, 'Würdigen heißt, kurz innezuhalten und anzuerkennen. Das schafft Raum für Verbindung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d38324bc-d000-4a3f-a909-0c700d82ce65', 'de', 'Die Energie ist hoch, aber du redest schon eine Weile. Was solltest du tun?', '["Weiterreden, um den Schwung zu halten", "Innehalten und fragen, was sie zu deinem Punkt meint", "Dich entschuldigen, dass du so viel redest", "Das Gespräch beenden"]'::jsonb, 'Frag nach, damit wieder ein Hin und Her entsteht und kein Monolog.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d45e9b83-7cd7-4c69-b73b-89ec09e1fe8d', 'de', 'Sie lacht und lehnt sich zu dir. Du willst ihre Nummer. Was funktioniert am besten?', '["„Tipp deine Nummer ein, das hier machen wir weiter.“", "„Würdest du mir vielleicht deine Nummer geben?“", "„Willst du in Kontakt bleiben?“", "„Vielleicht können wir mal schreiben?“"]'::jsonb, 'Wenn du ihr ganz selbstverständlich dein Handy gibst, fällt ihr ein Ja leicht, und sie kann trotzdem Nein sagen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d8feb1b5-d12d-4bee-96bc-68092a37c841', 'de', 'Warum ist ein Energieabfall nicht dasselbe wie Desinteresse?', '["Er kommt oft, wenn ein Thema ausgeschöpft ist", "Er kann von einem heiklen Thema kommen", "Er ist eine normale Reibungsstelle im Gesprächsfluss", "Alle oben genannten"]'::jsonb, 'Energietiefs sind normale Übergänge, keine Zeichen von Ablehnung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('de05395b-2be8-4a0f-a1a9-f8ccc2dea698', 'de', 'Was tragen Beobachtungen und Aussagen bei, was Fragen allein nicht leisten?', '["Sie senken den Druck", "Sie zeigen Aufmerksamkeit", "Sie verteilen die Mühe im Gespräch gerechter", "Sie zwingen sie zu antworten"]'::jsonb, 'Beobachtungen und Aussagen laden zu einer Antwort ein, ohne sie zu verlangen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('df1e06ae-6ab7-4483-aa1a-c651e45f6383', 'de', 'Welche nonverbalen Signale zeigen gutes Zuhören?', '["Dich ihr direkt zuwenden", "Natürlicher Blickkontakt", "Dich leicht vorlehnen", "Verschlossene Haltung und verschränkte Arme"]'::jsonb, 'Offene Körpersignale zeigen Interesse und geben ihr das Gefühl, geschätzt zu werden.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e32b283b-6ea1-4914-8d33-e58a17093c39', 'de', 'Sie sagt: „Die Bar hat eine tolle Atmosphäre.“ Welche Reaktion ist eine Beobachtung?', '["„Bist du oft hier?“", "„Ja, die Musik hier ist immer genau richtig.“", "„Was gefällt dir daran?“", "„Ist das deine Lieblingsbar?“"]'::jsonb, 'Eine Aussage teilt deine Sicht und macht es ihr leicht, darauf einzugehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e6a811b3-1df2-496e-a632-731de2c90037', 'de', 'Sie erzählt etwas, das ihr viel bedeutet. Welche Reaktion vertieft die emotionale Verbindung?', '["Würdigen, warum es ihr wichtig ist", "Lösungen anbieten", "Sofort eine ähnliche Geschichte erzählen", "Das Thema wechseln, damit es leicht bleibt"]'::jsonb, 'Wer sich gesehen fühlt, spürt Wärme und emotionale Sicherheit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f1489d76-0230-4524-9918-2a7b8ca71d2d', 'de', 'Was bringt es dem Gespräch, zuzuhören, um zu verstehen?', '["Sie fühlt sich wirklich gehört", "Du bekommst Subtext und Details mit", "Es entsteht eine natürlichere Verbindung", "Es beschleunigt den Gesprächsfluss"]'::jsonb, 'Volle Präsenz bringt euch auf eine Wellenlänge und macht aus Reden echtes Verstehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f4b3b908-47e7-45ae-9eb6-f5261d6f7325', 'de', 'Sie fragt nach deinen Reisen. Du erzählst deine komplette Route. Die Energie lässt nach. Was wäre besser?', '["Erst nach ihren Reisen fragen, bevor du von deinen erzählst", "Alle Highlights erzählen, das Langweilige weglassen", "Einen bestimmten, bedeutsamen Moment der Reise auswählen"]'::jsonb, 'Konzentrier dich auf das, was sie verstehen soll, nicht auf alles, was passiert ist.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f5c61ea0-9f18-4235-a9ab-6adb6c8b8aac', 'de', 'Warum schafft es Verbindung, auf den Subtext einzugehen?', '["Es zeigt, dass du emotional intelligent und aufmerksam bist", "Sie fühlt sich verstanden, weil du ihre eigentliche Botschaft gehört hast", "Es zeigt, dass du genauer hinhörst als andere", "Emotionale Antworten bauen schneller Anziehung auf als sachliche"]'::jsonb, 'Im Subtext steckt die eigentliche Botschaft. Geh darauf ein, damit sie sich wirklich verstanden fühlt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('faa961fa-7141-46c3-a897-d3e92bbb1ede', 'de', 'Warum ist Lachen ein so starker emotionaler Anker?', '["Es schafft im Moment ein gemeinsames positives Gefühl", "Es signalisiert soziale Dominanz", "Es zeigt Intelligenz", "Es lenkt von Peinlichkeit ab"]'::jsonb, 'Gemeinsames Lachen schafft sofort eine positive Verbindung und Leichtigkeit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fc6a4d99-9dc3-4483-b053-8182553c1e5c', 'de', 'Mit welcher Einstellung gehst du am besten mit einem Energieabfall im Gespräch um?', '["Ihn als normal sehen und ruhig umlenken", "Ihn als Versagen sehen und überkompensieren", "Ihn ignorieren und beim Thema bleiben", "Das Gespräch sofort beenden"]'::jsonb, 'Wer ruhig bleibt, behält die Fassung und bringt den Rhythmus ganz natürlich zurück.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fc8e3792-e6b6-47b1-b102-f1ec0d9d980b', 'de', 'Sie erwähnt einen Jobwechsel. Du hast selbst schon einen hinter dir. Beste Reaktion?', '["„Ich mach gerade dasselbe durch. Es ist furchtbar.“", "Ihren Kommentar ignorieren und das Thema wechseln", "„Ich hab auch schon mal gewechselt. Es war herausfordernd, aber hat sich gelohnt.“"]'::jsonb, 'Teil eine verarbeitete Erkenntnis, um eine Verbindung herzustellen, ohne zu viel Schmerz abzuladen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fe98319f-7a07-4376-a92b-a4c12040ed64', 'de', 'Warum schafft es psychologische Sicherheit, ihre Antwort zu würdigen?', '["Es erkennt an, dass ihre Erfahrungen zählen", "Sie fühlt sich verstanden und öffnet sich", "Es hetzt schnell zur nächsten Frage"]'::jsonb, 'Würdigen zeigt, dass ihre Worte angekommen sind, und fördert einen echten Austausch.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
